<template>
	<div class="h-full flex flex-col">
		<div v-if="crPage && crPage.doc_key === props.docKey" class="h-full flex flex-col">
			<div class="flex h-12 shrink-0 items-center gap-2 border-b border-outline-gray-2 bg-surface-base px-3 sm:px-5">
				<Breadcrumbs :items="breadcrumbs" class="min-w-0 flex-1" />

				<div class="flex shrink-0 items-center gap-2">
					<MergeChangeRequestButton v-if="!isMobile" />
					<SubmitForReviewButton />
					<FinishEditingButton />
					<Dropdown :options="menuOptions">
						<Button
							variant="ghost"
							:title="__('Page actions')"
							:aria-label="__('Page actions')"
						>
							<span class="lucide-more-horizontal size-4" aria-hidden="true" />
						</Button>
					</Dropdown>
				</div>
			</div>

			<!-- The one scroller on this page: the editor body scrolls under
			     the sticky toolbar, and the bubble menu and the outline rail
			     both measure against it. -->
			<ScrollArea v-if="!crPage.is_group" class="min-h-0 flex-1" viewport-class="pb-10">
				<WikiEditor v-if="editorKey" :key="editorKey" ref="editorRef" :content="editorContent" :document-key="props.docKey" :saved-content="savedContent" @save="saveContent" @save-all="flushOtherDirtyPages" @content-change="onEditorContentChange" @content-ready="onEditorContentReady">
					<template #title>
						<div class="pt-10">
							<div class="flex items-start gap-3">
								<input
									type="text"
									v-model="editableTitle"
									class="text-3xl-semibold text-ink-gray-9 bg-transparent border-none outline-none w-full min-w-0 flex-1 focus:ring-0 p-0 placeholder:text-ink-gray-4"
									:placeholder="__('Page title')"
									@blur="saveTitleIfChanged"
									@keydown.enter="$event.target.blur()"
								/>
								<div class="flex shrink-0 items-center gap-2 pt-2">
									<span
										v-if="isPageDirty"
										class="size-2 rounded-full bg-surface-amber-4"
										:title="__('Unsaved changes')"
										:aria-label="__('Unsaved changes')"
										role="status"
									/>
									<Badge variant="subtle" theme="blue" size="sm">
										{{ __('Draft') }}
									</Badge>
								</div>
							</div>
						</div>
					</template>
				</WikiEditor>
			</ScrollArea>

			<div v-else class="flex-1 flex flex-col overflow-auto">
				<div class="mx-auto w-full max-w-3xl px-8 pt-10">
					<div class="flex items-start gap-3">
						<input
							type="text"
							v-model="editableTitle"
							class="text-3xl-semibold text-ink-gray-9 bg-transparent border-none outline-none w-full min-w-0 flex-1 focus:ring-0 p-0 placeholder:text-ink-gray-4"
							:placeholder="__('Group name')"
							@blur="saveTitleIfChanged"
							@keydown.enter="$event.target.blur()"
						/>
						<div class="flex shrink-0 items-center gap-2 pt-2">
							<Badge variant="subtle" theme="blue" size="sm">{{ __('Draft') }}</Badge>
							<Badge variant="subtle" theme="gray" size="sm">{{ __('Group') }}</Badge>
						</div>
					</div>
				</div>
				<div class="flex-1 flex items-center justify-center text-ink-gray-5">
					<div class="text-center">
						<span class="lucide-folder size-12 mx-auto mb-4 text-ink-gray-4" aria-hidden="true" />
						<p>{{ __('This is a draft group.') }}</p>
						<p class="text-sm">{{ __('Groups organize pages but have no content.') }}</p>
					</div>
				</div>
			</div>
		</div>

		<div v-else-if="!loadFailed" class="h-full flex flex-col">
			<div class="flex h-12 shrink-0 items-center justify-between border-b border-outline-gray-2 px-3 sm:px-5">
				<Skeleton class="h-4 w-40 rounded-4" />
				<div class="flex items-center gap-2">
					<Skeleton class="h-8 w-16 rounded-4" />
					<Skeleton class="size-8 rounded-4" />
				</div>
			</div>
			<div class="mx-auto w-full max-w-3xl flex-1 px-8 pb-10 pt-10 space-y-4">
				<Skeleton class="h-8 w-64 rounded-4" />
				<Skeleton class="h-5 w-14 rounded-full" />
				<Skeleton class="h-4 w-3/4 rounded-4" />
				<Skeleton class="h-4 w-full rounded-4" />
				<Skeleton class="h-4 w-5/6 rounded-4" />
				<Skeleton class="h-4 w-full rounded-4" />
				<Skeleton class="h-4 w-2/3 rounded-4" />
				<Skeleton class="h-4 w-full rounded-4 mt-6" />
				<Skeleton class="h-4 w-4/5 rounded-4" />
				<Skeleton class="h-4 w-full rounded-4" />
			</div>
		</div>

		<div v-else class="h-full flex items-center justify-center text-ink-gray-5">
			<div class="text-center">
				<span class="lucide-alert-circle size-12 mx-auto mb-4 text-ink-gray-4" aria-hidden="true" />
				<p>{{ __('Draft not found') }}</p>
			</div>
		</div>
		<Dialog v-model:open="showRouteDialog" size="sm">
			<template #title>
				<h3 class="text-2xl-semibold text-ink-gray-9">{{ __('Edit Route') }}</h3>
			</template>
			<template #default>
				<FormControl
					v-model="editableRoute"
					:label="__('Route')"
					type="text"
					:placeholder="__('page-route')"
				/>
			</template>
			<template #actions="{ close }">
				<div class="flex justify-end gap-2">
					<Button variant="outline" @click="close">{{ __('Cancel') }}</Button>
					<Button variant="solid" :loading="isSavingRoute" @click="saveRoute(close)">
						{{ __('Update') }}
					</Button>
				</div>
			</template>
		</Dialog>
	</div>
</template>

<script setup>
import { SPACE_TREE_KEY, crumbRoute, trailToNode } from '@/lib/spaceTree';
import { useDraftWorkspaceStore } from '@/stores/draftWorkspace';
import {
	Badge,
	Breadcrumbs,
	Button,
	Dialog,
	Dropdown,
	FormControl,
	LoadingIndicator,
	ScrollArea,
	Skeleton,
	getCachedDocumentResource,
	toast,
	usePageMeta,
} from 'frappe-ui';
import { computed, inject, ref, watch } from 'vue';
import { useRouter } from 'vue-router';
import { useMobile } from '../composables/useMobile';
import FinishEditingButton from './FinishEditingButton.vue';
import MergeChangeRequestButton from './MergeChangeRequestButton.vue';
import SubmitForReviewButton from './SubmitForReviewButton.vue';
import WikiEditor from './WikiEditor.vue';

const props = defineProps({
	docKey: {
		type: String,
		required: true,
	},
	spaceId: {
		type: String,
		required: false,
	},
});

const emit = defineEmits(['refresh']);
const router = useRouter();
const editorRef = ref(null);
const editableTitle = ref('');
const editableRoute = ref('');
const showRouteDialog = ref(false);
const isSavingRoute = ref(false);

const draftStore = useDraftWorkspaceStore();
const { isMobile } = useMobile();

const crPage = ref(null);
// Becomes true only once we've confirmed the page genuinely doesn't exist,
// so the "Draft not found" state never flashes during a normal load/switch.
const loadFailed = ref(false);
// Guards against a slow response for a page we've already navigated away
// from overwriting the page the user is now looking at.
let loadToken = 0;

// Browser tab title: "{draft page} | {space}". Returning undefined while the
// draft is still loading keeps the previous title instead of flashing a blank one.
usePageMeta(() => {
	const title = crPage.value?.title;
	if (!title) return;
	const space = props.spaceId
		? getCachedDocumentResource('Wiki Space', props.spaceId)
		: null;
	return { title: [title, space?.doc?.space_name].filter(Boolean).join(' | ') };
});

const spaceTree = inject(SPACE_TREE_KEY, null);

// Same trail an already-merged page shows. A draft page is in the tree under
// its tmp key, so it reads its home before it is ever saved. The last crumb
// follows the title input rather than the stored title.
const breadcrumbs = computed(() => {
	const children = spaceTree?.value?.children;
	if (!children?.length) return [];

	const trail = trailToNode(children, (node) => node.doc_key === props.docKey);
	if (!trail) return [];

	return trail.map((node, i) => ({
		label:
			(i === trail.length - 1 ? editableTitle.value : node.title) ||
			__('Untitled'),
		route: crumbRoute(node, props.spaceId),
	}));
});

// Read the page through the workspace store. Tmp pages live entirely on the
// client; the store returns them from pagesByKey without hitting the
// backend (which would 404 on a tmp_* key).
//
// Stale-while-revalidate: if we already have this page cached in the store
// (a tmp create, a prior visit, or unsaved local edits) we paint it
// synchronously so switching pages is instant. The skeleton is reserved for
// the cold case where nothing is cached yet. The background fetch then
// revalidates whatever we showed.
async function loadCrPage() {
	const docKey = props.docKey;
	const token = ++loadToken;
	if (!docKey) {
		crPage.value = null;
		loadFailed.value = false;
		return;
	}
	loadFailed.value = false;

	const cached = draftStore.pagesByKey[docKey];
	if (cached) setCrPageFromStore(docKey, cached);

	try {
		const page = await draftStore.loadCrPage(docKey);
		if (token !== loadToken) return; // superseded by a newer navigation
		if (page) {
			setCrPageFromStore(docKey, page);
		} else if (
			draftStore.crName &&
			!(crPage.value && crPage.value.doc_key === docKey)
		) {
			// We have a change request but the page resolved to nothing —
			// it's genuinely missing (deleted / bad URL), not still loading.
			crPage.value = null;
			loadFailed.value = true;
		}
	} catch (error) {
		if (token !== loadToken) return;
		console.error('Error loading draft page:', error);
		if (!(crPage.value && crPage.value.doc_key === docKey)) {
			crPage.value = null;
			loadFailed.value = true;
		}
	}
}

function setCrPageFromStore(docKey, page = draftStore.pagesByKey[docKey]) {
	if (!page) {
		crPage.value = null;
		return;
	}
	const node = draftStore.findNode(docKey);
	crPage.value = {
		doc_key: docKey,
		title: page.title,
		route: page.route,
		content: page.localContent ?? page.content,
		is_published: page.isPublished,
		is_group: node?.isGroup || false,
	};
}

// The space store opens the change request; a direct load lands here first.
watch(
	() => draftStore.crName,
	async (name) => {
		if (!name) return;
		// A draft of this page saved in IndexedDB is restored during hydration.
		if (draftStore.isHydrating) {
			await draftStore.hydrateForPage(props.spaceId, props.docKey);
		}
		// Restored IndexedDB drafts may belong to pages never revisited.
		draftStore.flushDirtyPages(props.docKey).catch(() => {});
		await loadCrPage();
	},
	{ immediate: true },
);

watch(
	() => props.docKey,
	async (newId) => {
		if (newId) {
			// Navigation cancels the previous page's debounced autosave;
			// flush its buffer now. Failures surface via the sync pill.
			draftStore.flushDirtyPages(newId).catch(() => {});
			await loadCrPage();
		}
	},
);

// Drain dirty buffers for pages other than the one on screen; the open
// page's saves go through the editor instead.
async function flushOtherDirtyPages() {
	const failures = await draftStore.flushDirtyPages(props.docKey);
	if (failures.length) {
		const error = failures[0];
		toast.error(
			error?.messages?.[0] || error?.message || __('Error saving draft'),
		);
	}
}

function onEditorContentChange(content, docKey = props.docKey, options = {}) {
	if (!docKey) return;
	const title = draftStore.pagesByKey[docKey]?.title ?? editableTitle.value;
	draftStore.recordEditorContent(docKey, content, title, options);
}

function onEditorContentReady(content, savedContent, docKey = props.docKey) {
	if (!docKey) return;
	const title = draftStore.pagesByKey[docKey]?.title ?? editableTitle.value;
	draftStore.reconcileEditorContent(docKey, content, savedContent, title);
}

// Once the create syncs, swap the URL from /draft/tmp_* to /draft/realKey.
// Without this the panel would stay on a temp key after sync, and any
// reload would 404 on get_cr_page.
//
// Immediate, because the create can resolve before this panel mounts — the
// navigation to /draft/tmp_* and the create race each other, and on a fast
// bench the create wins. A lazy watcher then never fires for a key that was
// promoted moments earlier, stranding the page on "Draft not found".
watch(
	() => draftStore.tempKeyResolutions[props.docKey],
	(realKey) => {
		if (realKey && realKey !== props.docKey) {
			const currentContent = editorRef.value?.getMarkdown?.();
			if (currentContent !== undefined) {
				draftStore.updateLocalPageContent(
					realKey,
					currentContent,
					editableTitle.value,
				);
				draftStore
					.saveContent(realKey, currentContent, editableTitle.value)
					.catch((error) => {
						console.error('Error saving draft after create:', error);
						toast.error(
							error.messages?.[0] || error.message || __('Error saving draft'),
						);
					});
			}
			router.replace({
				name: 'DraftChangeRequest',
				params: { spaceId: props.spaceId, docKey: realKey },
			});
		}
	},
	{ immediate: true },
);

watch(
	crPage,
	(page) => {
		if (page) {
			editableTitle.value = page.title || '';
		}
	},
	{ immediate: true },
);

watch(
	() => draftStore.pagesByKey[props.docKey],
	(page) => {
		if (page) setCrPageFromStore(props.docKey, page);
	},
	{ deep: true },
);

const editorContent = computed(() => {
	return crPage.value?.content || '';
});

// Same divergence test the store's finalization gate uses, for this page.
const isPageDirty = computed(() => {
	const page = draftStore.pagesByKey[props.docKey];
	return Boolean(
		page?.localContent != null && page.localContent !== page.content,
	);
});
// The editor normalizes this confirmed snapshot before handing it back to
// the store for comparison.
const savedContent = computed(
	() => draftStore.pagesByKey[props.docKey]?.content ?? '',
);

const editorKey = computed(() => {
	if (crPage.value?.doc_key === props.docKey) {
		return `draft-${props.docKey}-${crPage.value?.doc_key}`;
	}
	return null;
});

const menuOptions = computed(() => {
	return [
		{
			label: __('Change route'),
			icon: 'lucide-link',
			onClick: openRouteDialog,
		},
		{
			label: __('Delete Draft'),
			icon: 'lucide-trash-2',
			onClick: deleteDraft,
		},
	];
});

async function saveTitleIfChanged() {
	const newTitle = editableTitle.value.trim();
	if (!newTitle || newTitle === (crPage.value?.title || '')) return;
	if (!crPage.value?.doc_key) return;
	try {
		await draftStore.updateNode(crPage.value.doc_key, { title: newTitle });
	} catch (error) {
		toast.error(error.messages?.[0] || __('Error updating title'));
	}
}

function openRouteDialog() {
	editableRoute.value = crPage.value?.route || '';
	showRouteDialog.value = true;
}

async function saveRoute(close) {
	const newRoute = editableRoute.value.trim().replace(/^\/+/, '');
	if (!newRoute || newRoute === (crPage.value?.route || '')) {
		close();
		return;
	}
	if (!crPage.value?.doc_key) return;
	isSavingRoute.value = true;
	try {
		await draftStore.updateNode(crPage.value.doc_key, { route: newRoute });
		close();
	} catch (error) {
		toast.error(error.messages?.[0] || __('Error updating route'));
	} finally {
		isSavingRoute.value = false;
	}
}

async function saveContent(content) {
	if (!crPage.value?.doc_key) return;
	try {
		await draftStore.saveContent(
			crPage.value.doc_key,
			content,
			editableTitle.value,
		);
	} catch (error) {
		// The sync alert says so and stays up; a toast per blocked autosave would not.
		if (error.code === 'version_conflict') return;
		console.error('Error saving draft:', error);
		// Inline failure UX comes in task #7; keep a toast for now so the
		// user isn't left wondering whether their save worked.
		toast.error(
			error.messages?.[0] || error.message || __('Error saving draft'),
		);
	}
}

async function deleteDraft() {
	if (!crPage.value?.doc_key) return;
	try {
		await draftStore.deleteNode(crPage.value.doc_key);
		router.push({ name: 'SpaceDetails', params: { spaceId: props.spaceId } });
	} catch (error) {
		console.error('Error deleting draft:', error);
		toast.error(error.messages?.[0] || __('Error deleting draft'));
	}
}
</script>
